type PageName = "home" | "shop" | "collections" | "new-arrivals" | "about" | "craftsmanship" | "gallery" | "contact" | "cart" | "wishlist" | "checkout";
type IconName = "search" | "bag" | "heart" | "menu" | "close" | "arrow" | "eye" | "edit" | "trash" | "phone" | "pin" | "mail" | "plus" | "minus" | "chevron";

function Icon({ name, size = 18 }: { name: IconName; size?: number }) {
  const paths: Record<IconName, ReactNode> = {
    search: <><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></>, bag: <><path d="M5 8h14l1 13H4L5 8Z"/><path d="M9 8a3 3 0 0 1 6 0"/></>, heart: <path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8l1.1 1.1L12 21l7.8-7.5 1.1-1.1a5.5 5.5 0 0 0-.1-7.8Z"/>, menu: <><path d="M3 6h18"/><path d="M3 12h18"/><path d="M3 18h18"/></>, close: <><path d="m18 6-12 12"/><path d="m6 6 12 12"/></>, arrow: <><path d="M5 12h14"/><path d="m13 6 6 6-6 6"/></>, eye: <><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></>, edit: <><path d="m15 5 4 4"/><path d="m4 20 4-.8L19 8a2.8 2.8 0 0 0-4-4L4 15l-.8 4Z"/></>, trash: <><path d="M4 7h16"/><path d="M10 11v6M14 11v6"/><path d="m5 7 1 14h12l1-14"/><path d="M9 7V4h6v3"/></>, phone: <><path d="M5 3h3l2 5-2 1c1.2 2.4 3.6 4.8 6 6l1-2 5 2v3c0 1-1 2-2 2C10 20 4 14 4 5c0-1 0-2 1-2Z"/></>, pin: <><path d="M20 10c0 5-8 11-8 11S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></>, mail: <><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m4 7 8 6 8-6"/></>, plus: <><path d="M12 5v14M5 12h14"/></>, minus: <path d="M5 12h14"/>, chevron: <path d="m6 9 6 6 6-6"/>,
  };
  return <svg aria-hidden="true" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">{paths[name]}</svg>;
}

const navItems = [["Home", "/"], ["Shop", "/shop"], ["Collections", "/collections"], ["New Arrivals", "/new-arrivals"], ["About Us", "/about"], ["Craftsmanship", "/craftsmanship"], ["Gallery", "/gallery"], ["Contact Us", "/contact"]] as const;
