function ProductCard({ product, compact = false, onQuickView }: { product: Product; compact?: boolean; onQuickView?: (product: Product) => void }) {
  const { state, addToCart, toggleWishlist } = useJewelryStore();
  const wished = state.wishlist.includes(product.id);
  return <article className="group min-w-0">
    <div className={`image-reveal relative bg-secondary ${compact ? "aspect-[4/5]" : "aspect-[4/5]"}`}>
      <Link to="/product/$slug" params={{ slug: product.slug }} aria-label={`View ${product.name}`}><img src={product.image} alt={product.name} loading="lazy" className="size-full object-cover"/></Link>
      {(product.newest || product.originalPrice) && <span className="absolute left-3 top-3 bg-background/90 px-2 py-1 text-[9px] tracking-[0.14em]">{product.newest ? "NEW ARRIVAL" : "A PRIVATE OFFER"}</span>}
      <Button variant="secondary" size="icon" aria-label={wished ? `Remove ${product.name} from wishlist` : `Add ${product.name} to wishlist`} onClick={() => toggleWishlist(product.id)} className="absolute right-3 top-3 size-9 bg-background/90"> <span className={wished ? "text-primary" : ""}><Icon name="heart" size={17}/></span></Button>
      <div className="absolute inset-x-3 bottom-3 flex translate-y-2 gap-2 opacity-0 transition-all duration-300 group-hover:translate-y-0 group-hover:opacity-100 group-focus-within:translate-y-0 group-focus-within:opacity-100">
        <Button variant="secondary" onClick={() => onQuickView?.(product)} className="h-10 flex-1 bg-background/95 text-[10px] uppercase tracking-[0.14em]">Quick view</Button>
        <Button onClick={() => addToCart(product.id)} className="h-10 flex-1 text-[10px] uppercase tracking-[0.14em]">Add to bag</Button>
      </div>
    </div>
    <div className="pt-4"><p className="mb-1 text-[9px] tracking-[0.15em] text-muted-foreground">{product.category.toUpperCase()} · {product.metal}</p><Link to="/product/$slug" params={{ slug: product.slug }} className="font-editorial text-lg hover:text-primary">{product.name}</Link><div className="mt-2 flex items-center gap-2 text-sm"><span>{money(product.price)}</span>{product.originalPrice && <del className="text-xs text-muted-foreground">{money(product.originalPrice)}</del>}</div></div>
  </article>;
}

