function ProductModal({ product, close }: { product: Product | null; close: () => void }) {
  const { addToCart } = useJewelryStore();
  if (!product) return null;
  return <div role="dialog" aria-modal="true" aria-label={`${product.name} quick view`} className="fixed inset-0 z-50 flex items-center justify-center bg-foreground/55 p-4" onMouseDown={(event) => { if (event.target === event.currentTarget) close(); }}><div className="relative grid w-full max-w-3xl bg-background md:grid-cols-2"><Button variant="ghost" size="icon" aria-label="Close" onClick={close} className="absolute right-2 top-2 z-10"><Icon name="close"/></Button><img src={product.image} alt={product.name} className="max-h-[70vh] w-full object-cover"/><div className="flex flex-col justify-center p-7 md:p-10"><p className="text-[10px] tracking-widest text-primary">{product.category.toUpperCase()}</p><h2 className="mt-3 font-editorial text-3xl">{product.name}</h2><p className="mt-3 text-lg">{money(product.price)}</p><p className="mt-5 text-sm leading-6 text-muted-foreground">{product.description}</p><Button className="mt-7" onClick={() => { addToCart(product.id); close(); }}>Add to bag</Button><Link to="/product/$slug" params={{ slug: product.slug }} onClick={close} className="mt-4 text-center text-xs tracking-widest underline underline-offset-4">VIEW DETAILS</Link></div></div></div>;
}

