function ShopPage({ arrivalsOnly = false }: { arrivalsOnly?: boolean }) {
  const { state } = useJewelryStore();
  const [category, setCategory] = useState("All jewellery");
  const [metal, setMetal] = useState("All metals");
  const [sort, setSort] = useState("featured");
  const [query, setQuery] = useState("");
  const [maxPrice, setMaxPrice] = useState(500000);
  const [view, setView] = useState<"grid" | "list">("grid");
  const [quick, setQuick] = useState<Product | null>(null);
  const products = useMemo(() => {
    const filtered = state.products.filter((item) => (!arrivalsOnly || item.newest) && (category === "All jewellery" || item.category === category) && (metal === "All metals" || item.metal.toLowerCase().includes(metal.toLowerCase())) && item.price <= maxPrice && item.name.toLowerCase().includes(query.toLowerCase()));
    return filtered.sort((a, b) => sort === "low" ? a.price - b.price : sort === "high" ? b.price - a.price : sort === "newest" ? Number(b.newest) - Number(a.newest) : Number(b.featured) - Number(a.featured));
  }, [state.products, arrivalsOnly, category, metal, maxPrice, query, sort]);
  const categories = ["All jewellery", ...new Set(state.products.map((p) => p.category))];
  return <div className="page-enter"><PageIntro eyebrow={arrivalsOnly ? "FRESH FROM THE ATELIER" : "THE DHairya COLLECTION"} title={arrivalsOnly ? "New arrivals" : "Find a piece to keep"} copy="A considered selection of fine jewellery, made for the moments that matter."/><div className="mx-auto max-w-[1440px] px-5 py-11 md:px-12"><div className="mb-8 flex flex-col gap-4 border-b border-border pb-5 lg:flex-row lg:items-end lg:justify-between"><div className="grid gap-3 sm:grid-cols-2 lg:flex lg:items-center"><input aria-label="Search products" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search designs" className="h-10 border-b border-border bg-transparent px-2 text-sm outline-none focus:border-primary"/><select aria-label="Category" value={category} onChange={(e) => setCategory(e.target.value)} className="h-10 border-b border-border bg-background px-2 text-sm"><option>All jewellery</option>{categories.slice(1).map((name) => <option key={name}>{name}</option>)}</select><select aria-label="Metal type" value={metal} onChange={(e) => setMetal(e.target.value)} className="h-10 border-b border-border bg-background px-2 text-sm"><option>All metals</option>{[...new Set(state.products.map((p) => p.metal))].map((item) => <option key={item}>{item}</option>)}</select><label className="flex items-center gap-2 text-xs text-muted-foreground">Up to {money(maxPrice)}<input aria-label="Maximum price" type="range" min="20000" max="500000" step="10000" value={maxPrice} onChange={(e) => setMaxPrice(Number(e.target.value))} className="w-24 accent-primary"/></label></div><div className="flex items-center justify-between gap-3 text-xs"><span>{products.length} designs</span><select aria-label="Sort products" value={sort} onChange={(e) => setSort(e.target.value)} className="h-9 border-b border-border bg-background px-2"><option value="featured">Featured</option><option value="newest">Newest arrivals</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option></select><Button variant="ghost" size="sm" onClick={() => setView(view === "grid" ? "list" : "grid")} aria-label={`Switch to ${view === "grid" ? "list" : "grid"} view`}>{view === "grid" ? "LIST" : "GRID"}</Button></div></div>{products.length ? <div className={view === "grid" ? "grid grid-cols-2 gap-x-4 gap-y-9 sm:gap-x-6 lg:grid-cols-4" : "grid grid-cols-1 gap-4 sm:grid-cols-2"}>{products.slice(0, 24).map((product) => <ProductCard key={product.id} product={product} onQuickView={setQuick}/>)}</div> : <p className="py-24 text-center font-editorial text-2xl">No designs match those filters.</p>}</div><ProductModal product={quick} close={() => setQuick(null)}/></div>;
}

function CollectionsPage() {
  const { state } = useJewelryStore();
  const images = ["/images/bridal-necklace.png", "/images/gold-necklace.png", "/images/diamond-earrings.png", "/images/diamond-bracelet.png", "/images/gold-earrings.png", "/images/mens-ring.png", "/images/sapphire-pendant.png", "/images/gold-bangles.png"];
  return <div className="page-enter"><PageIntro eyebrow="CURATED BY DHairya" title="Collections, with character" copy="Distinct expressions of craft, from celebratory heirlooms to the pieces that make an ordinary day feel special."/><section className="mx-auto max-w-[1440px] px-5 py-12 md:px-12"><div className="grid gap-7 sm:grid-cols-2 lg:grid-cols-4">{collections.map((name, i) => { const products = state.products.filter((p) => p.collection.toLowerCase() === name.toLowerCase()); return <article key={name}><Link to="/collections/$slug" params={{ slug: slugify(name) }} className="image-reveal group relative block aspect-[4/5] bg-secondary"><img src={images[i] ?? "/images/gold-necklace.png"} alt={`${name} jewellery collection`} loading="lazy" className="size-full object-cover"/><div className="absolute inset-0 bg-gradient-to-t from-foreground/60 to-transparent"/><div className="absolute inset-x-4 bottom-5 text-background"><h2 className="font-editorial text-2xl">{name === "Bridal" ? "Bridal Collection" : name === "Royal Gold" ? "Royal Gold Collection" : name}</h2><p className="mt-2 text-[10px] tracking-widest">{products.length} DESIGNS <span className="ml-2">→</span></p></div></Link><p className="mt-3 text-xs leading-5 text-muted-foreground">A distinctive point of view, expressed through considered form and detail.</p></article>; })}</div></section></div>;
}

function EditorialPage({ kind }: { kind: "about" | "craftsmanship" }) {
  const craft = kind === "craftsmanship";
  const stages = [["01", "Concept & design", "A thoughtful form starts with a line, a feeling, and a sketch."], ["02", "Metal selection", "The material gives every silhouette its own character."], ["03", "Precision crafting", "Careful hands shape the details that make a piece feel personal."], ["04", "Gemstone setting", "Each stone is considered for its place, proportion and light."], ["05", "Polishing & finishing", "The final surface brings clarity and life to every curve."], ["06", "Final review", "A considered final check completes this illustrative process."]];
  return <div className="page-enter">{craft ? <PageIntro eyebrow="MADE WITH INTENTION" title="The making is part of the meaning" copy="A look at the considered steps behind a piece of jewellery. This is an editorial overview of the craft."/> : <PageIntro eyebrow="ABOUT DHAIRYA" title="Jewellery for the moments that stay" copy="Dhairya Gems and Jewels Private Limited brings together jewellery manufacturing expertise, thoughtful design and a love of precious materials."/>}<section className="mx-auto grid max-w-[1440px] gap-10 px-5 py-14 md:grid-cols-2 md:items-center md:px-12"><div className="image-reveal aspect-[4/5] max-h-[620px]"><img src={craft ? "/images/craftsmanship.png" : "/images/bridal-necklace.png"} alt={craft ? "A fine jeweller carefully setting a gemstone" : "Intricate bridal gold and gemstone jewellery"} loading="lazy" className="size-full object-cover"/></div><div className="md:pl-12"><p className="text-[10px] tracking-[0.2em] text-primary">{craft ? "AN ART THAT REWARDS PATIENCE" : "A NOTE ON OUR PHILOSOPHY"}</p><h2 className="mt-4 font-editorial text-4xl leading-tight sm:text-5xl">{craft ? "Every detail has a reason." : "Designed to feel like yours."}</h2><p className="mt-5 text-sm leading-7 text-muted-foreground">{craft ? "From a first idea to the finished form, making fine jewellery calls for curiosity, precision and an appreciation of the materials. Each step is an opportunity to make something considered." : "Our work spans gold, silver and other precious and base metals, precious and semi-precious stones, and the combinations that bring a design to life. We believe true elegance is both expressive and enduring."}</p><p className="mt-4 text-sm leading-7 text-muted-foreground">{craft ? "The process shown here is an illustrative look at the work. Product specifications throughout this demo are sample details only." : "We are a Mumbai jewellery manufacturing business serving the many ways people choose to mark a moment, celebrate a bond, or simply wear what they love."}</p></div></section>{craft ? <section className="bg-secondary px-5 py-16 md:px-12"><SectionHeading eyebrow="FROM IDEA TO FINISH" title="A considered process"/><div className="mx-auto grid max-w-[1440px] gap-8 sm:grid-cols-2 lg:grid-cols-3">{stages.map(([number, title, copy], i) => <article key={number} className="grid grid-cols-[48px_1fr] gap-4 border-t border-primary/50 pt-5"><span className="font-editorial text-2xl text-primary">{number}</span><div><h3 className="font-editorial text-2xl">{title}</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">{copy}</p></div>{i === 2 && <img src="/images/craftsmanship.png" alt="Handwork at a jeweller's bench" loading="lazy" className="col-span-2 mt-2 aspect-video w-full object-cover"/>}</article>)}</div></section> : <section className="bg-foreground px-5 py-16 text-center text-background"><p className="text-[10px] tracking-[0.2em] text-primary">OUR VALUES</p><div className="mx-auto mt-8 grid max-w-5xl gap-8 sm:grid-cols-3">{[["Thoughtful design", "A point of view that leaves room for your own."], ["Careful making", "Respect for material, proportion and detail."], ["Personal meaning", "Jewellery is at its best when it becomes part of your story."]].map(([title, copy]) => <div key={title} className="border-t border-primary/60 pt-5"><h3 className="font-editorial text-2xl">{title}</h3><p className="mt-2 text-sm leading-6 text-background/65">{copy}</p></div>)}</div></section>}</div>;
}

function GalleryPage() {
  const { state } = useJewelryStore();
  const [filter, setFilter] = useState("All");
  const [lightbox, setLightbox] = useState<string | null>(null);
  const options = ["All", ...new Set(state.gallery.map((item) => String(item.category ?? "Jewellery")))];
  const images = state.gallery.filter((item) => filter === "All" || item.category === filter);
  return <div className="page-enter"><PageIntro eyebrow="A CLOSER LOOK" title="The details, in their own light" copy="A visual journal of jewellery, materials and the hands behind the work."/><section className="mx-auto max-w-[1440px] px-5 py-12 md:px-12"><div className="mb-7 flex flex-wrap justify-center gap-2">{options.map((option) => <Button key={option} size="sm" variant={filter === option ? "default" : "outline"} className="rounded-none text-[9px] tracking-widest" onClick={() => setFilter(option)}>{option}</Button>)}</div><div className="columns-2 gap-4 md:columns-3 lg:columns-4">{images.map((item) => <button key={item.id} onClick={() => setLightbox(String(item.image))} className="image-reveal mb-4 block w-full break-inside-avoid bg-secondary text-left"><img src={String(item.image)} alt={`${item.name} jewellery gallery`} loading="lazy" className="w-full object-cover transition-transform duration-700 hover:scale-105"/><span className="block px-3 py-3 font-editorial text-lg">{item.name}</span></button>)}</div></section>{lightbox && <div role="dialog" aria-modal="true" aria-label="Gallery image" className="fixed inset-0 z-50 flex items-center justify-center bg-foreground/90 p-4" onClick={() => setLightbox(null)}><button className="absolute right-5 top-5 text-2xl text-background" aria-label="Close image">×</button><img src={lightbox} alt="Enlarged jewellery gallery image" className="max-h-[88vh] max-w-full object-contain"/></div>}</div>;
}

function ContactPage() {
  const { state, update } = useJewelryStore();
  const [sent, setSent] = useState(false);
  const onSubmit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const enquiry = Object.fromEntries(data.entries()); update({ enquiries: [...state.enquiries, { id: `enquiry-${Date.now()}`, ...enquiry, status: "New" }] }); setSent(true); event.currentTarget.reset(); };
  return <div className="page-enter"><PageIntro eyebrow="WE WOULD LOVE TO HEAR FROM YOU" title="A conversation begins here" copy="Questions about a design, a collection or a visit? Write to us and our team will be glad to help."/><section className="mx-auto grid max-w-6xl gap-12 px-5 py-14 md:grid-cols-[.85fr_1.15fr] md:px-12"><div><p className="text-[10px] tracking-[0.2em] text-primary">COME SAY HELLO</p><h2 className="mt-3 font-editorial text-3xl">Dhairya Gems and Jewels Private Limited</h2><div className="mt-8 space-y-5 text-sm leading-6 text-muted-foreground"><p className="flex gap-3"><Icon name="pin"/><span>{state.settings.address}<a className="mt-2 block text-foreground underline underline-offset-4" href="https://maps.google.com/?q=Zaveri+Bazaar+Mumbai" target="_blank" rel="noreferrer">View on Google Maps</a></span></p><p className="flex items-center gap-3"><Icon name="phone"/><a href={`tel:${state.settings.phone}`}>{state.settings.phone}</a></p><p className="flex items-center gap-3"><Icon name="mail"/><a href={`mailto:${state.settings.email}`}>{state.settings.email}</a></p></div><p className="mt-8 border-t border-border pt-5 text-xs leading-5 text-muted-foreground">This demonstration does not send messages to the company. Form submissions are saved locally in the demo admin.</p></div><form onSubmit={onSubmit} className="grid gap-4 sm:grid-cols-2">{[["name", "Name", "text"], ["email", "Email", "email"], ["phone", "Phone", "tel"], ["subject", "Subject", "text"]].map(([name, label, type]) => <label key={name} className="grid gap-2 text-[10px] tracking-widest text-muted-foreground">{label.toUpperCase()}<input required name={name} type={type} className="h-11 border-b border-border bg-transparent px-1 text-sm text-foreground outline-none focus:border-primary"/></label>)}<label className="sm:col-span-2 grid gap-2 text-[10px] tracking-widest text-muted-foreground">MESSAGE<textarea required name="message" rows={5} minLength={10} className="resize-y border-b border-border bg-transparent px-1 py-2 text-sm text-foreground outline-none focus:border-primary"/></label><div className="sm:col-span-2"><Button type="submit" className="h-11 rounded-none px-8 text-[10px] tracking-widest">SEND AN ENQUIRY</Button>{sent && <p role="status" className="mt-3 text-sm text-primary">Thank you. Your demo enquiry has been saved.</p>}</div></form></section></div>;
}

function CartPage() {
  const { state, setQuantity, removeFromCart } = useJewelryStore();
  const items = state.cart.map((line) => ({ line, product: state.products.find((product) => product.id === line.productId) })).filter((entry): entry is { line: { productId: string; quantity: number }; product: Product } => Boolean(entry.product));
  const subtotal = items.reduce((sum, item) => sum + item.product.price * item.line.quantity, 0);
  if (!items.length) return <div className="page-enter"><PageIntro eyebrow="YOUR SELECTION" title="Your bag is waiting" copy="The pieces you choose will be gathered here."/><div className="py-12 text-center"><Button asChild className="rounded-none px-8 text-[10px] tracking-widest"><Link to="/shop">EXPLORE THE COLLECTION</Link></Button></div></div>;
  return <div className="page-enter"><PageIntro eyebrow="YOUR SELECTION" title="Your shopping bag" copy="A considered selection, saved for you."/><section className="mx-auto grid max-w-6xl gap-10 px-5 py-12 md:grid-cols-[1.4fr_.6fr] md:px-12"><div className="divide-y divide-border">{items.map(({ line, product }) => <div key={line.productId} className="grid grid-cols-[96px_1fr_auto] gap-4 py-5"><Link to="/product/$slug" params={{ slug: product.slug }}><img src={product.image} alt={product.name} className="aspect-[4/5] w-24 object-cover"/></Link><div><Link to="/product/$slug" params={{ slug: product.slug }} className="font-editorial text-xl">{product.name}</Link><p className="mt-1 text-xs text-muted-foreground">{product.metal}</p><div className="mt-4 flex items-center gap-2"><Button variant="outline" size="icon" aria-label="Decrease quantity" onClick={() => setQuantity(product.id, line.quantity - 1)} className="size-7"><Icon name="minus" size={14}/></Button><span className="w-6 text-center text-sm">{line.quantity}</span><Button variant="outline" size="icon" aria-label="Increase quantity" onClick={() => setQuantity(product.id, line.quantity + 1)} className="size-7"><Icon name="plus" size={14}/></Button></div><button onClick={() => removeFromCart(product.id)} className="mt-3 text-[9px] tracking-widest text-muted-foreground underline">REMOVE</button></div><p className="text-sm">{money(product.price * line.quantity)}</p></div>)}</div><aside className="h-fit border border-border p-6"><h2 className="font-editorial text-2xl">Order summary</h2><div className="mt-6 flex justify-between text-sm"><span>Subtotal</span><span>{money(subtotal)}</span></div><div className="mt-3 flex justify-between text-sm text-muted-foreground"><span>Estimated delivery</span><span>Complimentary</span></div><p className="mt-5 border-t border-border pt-4 text-[10px] leading-5 text-muted-foreground">Demo discount: 5% off the subtotal is applied at checkout.</p><Button asChild className="mt-5 w-full rounded-none text-[10px] tracking-widest"><Link to="/checkout">CONTINUE TO CHECKOUT</Link></Button><Button asChild variant="link" className="mt-2 w-full text-xs"><Link to="/shop">Continue shopping</Link></Button></aside></section></div>;
}

function WishlistPage() {
  const { state } = useJewelryStore();
  const products = state.products.filter((product) => state.wishlist.includes(product.id));
  return <div className="page-enter"><PageIntro eyebrow="SAVED FOR LATER" title="Your wishlist" copy="The pieces that caught your eye, all in one place."/><section className="mx-auto max-w-[1440px] px-5 py-12 md:px-12">{products.length ? <ProductGrid products={products}/> : <p className="py-12 text-center text-sm text-muted-foreground">Your wishlist is waiting for its first piece.</p>}</section></div>;
}

function CheckoutPage() {
  const { state, update } = useJewelryStore();
  const items = state.cart.map((line) => ({ line, product: state.products.find((product) => product.id === line.productId) })).filter((entry): entry is { line: { productId: string; quantity: number }; product: Product } => Boolean(entry.product));
  const subtotal = items.reduce((sum, item) => sum + item.product.price * item.line.quantity, 0);
  const discount = Math.round(subtotal * 0.05);
  const [orderId, setOrderId] = useState("");
  const navigate = useNavigate();
  const onSubmit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!items.length) return; const form = new FormData(event.currentTarget); const orderNumber = `DGJ-${Date.now().toString().slice(-7)}`; const order: DemoOrder = { id: orderNumber, name: String(form.get("name")), email: String(form.get("email")), phone: String(form.get("phone")), total: subtotal - discount, status: "Pending", date: new Date().toLocaleDateString("en-IN"), items: state.cart, address: `${String(form.get("address"))}, ${String(form.get("city"))}, ${String(form.get("state"))} ${String(form.get("pin"))}` }; update({ orders: [order, ...state.orders], customers: state.customers.some((customer) => customer.email === order.email) ? state.customers : [...state.customers, { id: `customer-${Date.now()}`, name: order.name, email: order.email, phone: order.phone, status: "Active" }], cart: [] }); localStorage.setItem("dhairya-last-order", orderNumber); setOrderId(orderNumber); navigate({ to: "/order-confirmation" }); };
  if (orderId) return <div className="mx-auto max-w-xl px-5 py-24 text-center"><span className="mx-auto flex size-14 items-center justify-center border border-primary font-editorial text-2xl text-primary">✓</span><p className="mt-6 text-[10px] tracking-widest text-primary">DEMO ORDER PLACED</p><h1 className="mt-3 font-editorial text-4xl">Thank you for your order</h1><p className="mt-4 text-sm leading-6 text-muted-foreground">Your demo order <strong>{orderId}</strong> has been saved locally. No payment was taken.</p><Button asChild className="mt-8 rounded-none"><Link to="/shop">CONTINUE EXPLORING</Link></Button></div>;
  if (!items.length) return <div className="page-enter"><PageIntro eyebrow="DEMO CHECKOUT" title="Your bag is empty" copy="Add a design to your bag before continuing to checkout."/><div className="py-10 text-center"><Button asChild><Link to="/shop">SHOP DESIGNS</Link></Button></div></div>;
  return <div className="page-enter"><PageIntro eyebrow="A SECURE-FEELING DEMO" title="Checkout" copy="Demonstration only. No payment credentials are collected and no payment is processed."/><section className="mx-auto grid max-w-6xl gap-10 px-5 py-12 md:grid-cols-[1.2fr_.8fr] md:px-12"><form onSubmit={onSubmit} className="grid gap-4 sm:grid-cols-2"><p className="sm:col-span-2 text-[10px] tracking-widest text-primary">CONTACT &amp; DELIVERY</p>{[["name", "Full name", "text"], ["email", "Email", "email"], ["phone", "Phone", "tel"], ["pin", "PIN code", "text"], ["address", "Shipping address", "text"], ["city", "City", "text"], ["state", "State", "text"]].map(([name, label, type]) => <label key={name} className={`grid gap-2 text-[10px] tracking-widest text-muted-foreground ${name === "address" ? "sm:col-span-2" : ""}`}>{label.toUpperCase()}<input required name={name} type={type} className="h-11 border-b border-border bg-transparent px-1 text-sm text-foreground outline-none focus:border-primary"/></label>)}<fieldset className="sm:col-span-2"><legend className="mb-3 text-[10px] tracking-widest text-muted-foreground">PAYMENT METHOD · DEMO ONLY</legend><label className="flex items-center gap-3 border border-border p-4 text-sm"><input type="radio" name="payment" value="demo" defaultChecked/> Demonstration order — no payment</label></fieldset><Button type="submit" className="h-12 rounded-none sm:col-span-2">PLACE DEMO ORDER · {money(subtotal - discount)}</Button><p className="sm:col-span-2 text-center text-[10px] leading-5 text-muted-foreground">Do not enter payment card details. This demonstration does not process payments.</p></form><aside className="h-fit border border-border p-6"><h2 className="font-editorial text-2xl">Order summary</h2>{items.map(({ product, line }) => <div key={product.id} className="flex justify-between gap-4 border-b border-border py-4 text-sm"><span>{product.name} × {line.quantity}</span><span>{money(product.price * line.quantity)}</span></div>)}<div className="mt-5 flex justify-between text-sm"><span>Subtotal</span><span>{money(subtotal)}</span></div><div className="mt-3 flex justify-between text-sm text-primary"><span>Demo discount (5%)</span><span>−{money(discount)}</span></div><div className="mt-5 flex justify-between border-t border-border pt-5 font-medium"><span>Total</span><span>{money(subtotal - discount)}</span></div></aside></section></div>;
}

export function ProductDetail({ slug }: { slug: string }) {
  const { state, addToCart, toggleWishlist, update } = useJewelryStore();
  const product = state.products.find((item) => item.slug === slug);
  const [quantity, setQuantity] = useState(1);
  const [selectedImage, setSelectedImage] = useState("");
  const [notice, setNotice] = useState("");
  if (!product) return <div className="px-5 py-28 text-center"><h1 className="font-editorial text-4xl">Piece not found</h1><Button asChild className="mt-6"><Link to="/shop">Return to the collection</Link></Button></div>;
  const gallery = [product.image, product.category === "Rings" ? "/images/diamond-ring.png" : product.category === "Earrings" ? "/images/gold-earrings.png" : "/images/craftsmanship.png"];
  const recent = [product.id, ...state.products.filter((item) => item.id !== product.id).slice(0, 3).map((item) => item.id)];
  const related = state.products.filter((item) => item.id !== product.id && (item.category === product.category || item.collection === product.collection)).slice(0, 4);
  return <div className="page-enter"><div className="mx-auto max-w-[1440px] px-5 py-6 text-[10px] tracking-widest text-muted-foreground md:px-12"><Link to="/shop">SHOP</Link> / {product.category.toUpperCase()} / {product.name.toUpperCase()}</div><section className="mx-auto grid max-w-[1440px] gap-8 px-5 pb-16 md:grid-cols-[1.15fr_.85fr] md:px-12"><div className="grid gap-3 sm:grid-cols-[74px_1fr]"><div className="order-2 flex gap-2 overflow-auto sm:order-1 sm:flex-col">{gallery.map((src, i) => <button key={`${src}-${i}`} onClick={() => setSelectedImage(src)} className={`w-[62px] shrink-0 border ${selectedImage === src ? "border-primary" : "border-border"}`} aria-label={`View product image ${i + 1}`}><img src={src} alt="" className="aspect-[4/5] size-full object-cover"/></button>)}</div><button onClick={() => setSelectedImage(selectedImage ? "" : product.image)} title="Select to toggle gallery view" className="image-reveal order-1 aspect-[4/5] max-h-[760px] cursor-zoom-in bg-secondary sm:order-2"><img src={selectedImage || product.image} alt={product.name} className="size-full object-cover"/></button></div><div className="flex flex-col justify-center md:pl-12"><p className="text-[10px] tracking-[0.2em] text-primary">{product.category.toUpperCase()} · {product.collection.toUpperCase()}</p><h1 className="mt-4 font-editorial text-4xl leading-tight sm:text-5xl">{product.name}</h1><div className="mt-4 flex items-center gap-3"><span className="text-xl">{money(product.price)}</span>{product.originalPrice && <del className="text-sm text-muted-foreground">{money(product.originalPrice)}</del>}</div><p className="mt-6 text-sm leading-7 text-muted-foreground">{product.description}</p><p className="mt-5 text-[10px] leading-5 text-muted-foreground">Product specifications below are illustrative demo data and are not verified product claims.</p><div className="mt-6 grid grid-cols-2 border-y border-border py-4 text-sm"><div className="py-2"><span className="block text-[9px] tracking-widest text-muted-foreground">SKU</span>{product.sku}</div><div className="py-2"><span className="block text-[9px] tracking-widest text-muted-foreground">METAL</span>{product.metal}</div><div className="py-2"><span className="block text-[9px] tracking-widest text-muted-foreground">PURITY</span>Demo specification</div><div className="py-2"><span className="block text-[9px] tracking-widest text-muted-foreground">WEIGHT</span>{product.weight}</div><div className="col-span-2 py-2"><span className="block text-[9px] tracking-widest text-muted-foreground">STONE DETAILS</span>{product.stone}</div></div><div className="mt-7 flex gap-3"><div className="flex items-center border border-border"><Button variant="ghost" size="icon" aria-label="Decrease quantity" onClick={() => setQuantity(Math.max(1, quantity - 1))}><Icon name="minus" size={14}/></Button><span className="w-8 text-center text-sm">{quantity}</span><Button variant="ghost" size="icon" aria-label="Increase quantity" onClick={() => setQuantity(quantity + 1)}><Icon name="plus" size={14}/></Button></div><Button className="h-11 flex-1 rounded-none text-[10px] tracking-widest" onClick={() => { addToCart(product.id, quantity); setNotice("Added to your shopping bag."); }}>ADD TO BAG</Button><Button variant="outline" size="icon" aria-label="Add to wishlist" onClick={() => { toggleWishlist(product.id); setNotice("Wishlist updated."); }}><Icon name="heart"/></Button></div>{notice && <p role="status" className="mt-3 text-sm text-primary">{notice} <Link to="/cart" className="underline">View bag</Link></p>}<Button variant="outline" className="mt-3 h-11 rounded-none" onClick={() => { addToCart(product.id, quantity); update({ homepage: { ...state.homepage } }); window.location.href = "/checkout"; }}>BUY NOW · DEMO CHECKOUT</Button></div></section><section className="border-t border-border px-5 py-12 md:px-12"><div className="mx-auto max-w-[1440px]"><SectionHeading eyebrow="YOU MAY ALSO LOVE" title="A few more to discover"/><ProductGrid products={related.length ? related : state.products.slice(0, 4)}/><div className="mt-10 flex items-center justify-center gap-2 text-[10px] text-muted-foreground">RECENTLY VIEWED <span>{recent.length} PIECES</span></div></div></section></div>;
}

function AdminLogin() {
  const [error, setError] = useState("");
  const [ok, setOk] = useState(false);
  const onSubmit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); if (data.get("email") === "admin@dhairyagemsandjewels.com" && data.get("password") === "Admin@123") { localStorage.setItem("dhairya-admin-demo-session", "active"); setOk(true); window.location.href = "/admin/dashboard"; } else setError("Those demo credentials do not match."); };
  return <div className="flex min-h-screen items-center justify-center bg-secondary px-5 py-12"><div className="w-full max-w-md bg-background p-8 shadow-sm sm:p-10"><div className="flex justify-center"><BrandMark/></div><p className="mt-8 text-center text-[10px] tracking-[0.2em] text-primary">DEMO ADMINISTRATION</p><h1 className="mt-2 text-center font-editorial text-3xl">Welcome back</h1><p className="mt-2 text-center text-xs leading-5 text-muted-foreground">Use the demonstration credentials to enter the sample dashboard.</p><form onSubmit={onSubmit} className="mt-8 grid gap-5"><label className="grid gap-2 text-[10px] tracking-widest">EMAIL<input required type="email" name="email" defaultValue="admin@dhairyagemsandjewels.com" className="h-11 border-b border-border bg-transparent px-1 text-sm outline-none focus:border-primary"/></label><label className="grid gap-2 text-[10px] tracking-widest">PASSWORD<input required type="password" name="password" defaultValue="Admin@123" className="h-11 border-b border-border bg-transparent px-1 text-sm outline-none focus:border-primary"/></label><Button type="submit" className="mt-2 h-11 rounded-none tracking-widest">SIGN IN TO DEMO</Button>{error && <p role="alert" className="text-sm text-destructive">{error}</p>}{ok && <p className="text-sm text-primary">Opening dashboard…</p>}</form><p className="mt-6 text-center text-[10px] leading-5 text-muted-foreground">Demo only. This is not secure authentication. <br/>Email: admin@dhairyagemsandjewels.com<br/>Password: Admin@123</p><Link to="/" className="mt-7 block text-center text-xs underline">Return to storefront</Link></div></div>;
}

const moduleLabels: Record<string, keyof Pick<ReturnType<typeof useJewelryStore>["state"], "categories" | "collections" | "orders" | "customers" | "banners" | "gallery" | "testimonials" | "coupons" | "newsletter" | "enquiries">> = {
  categories: "categories", collections: "collections", orders: "orders", customers: "customers", banners: "banners", gallery: "gallery", testimonials: "testimonials", coupons: "coupons", newsletter: "newsletter", enquiries: "enquiries",
};
const adminNav = [["Overview", "/admin/dashboard"], ["Products", "/admin/products"], ["Categories", "/admin/categories"], ["Collections", "/admin/collections"], ["Orders", "/admin/orders"], ["Customers", "/admin/customers"], ["Banners", "/admin/banners"], ["Gallery", "/admin/gallery"], ["Testimonials", "/admin/testimonials"], ["Coupons", "/admin/coupons"], ["Newsletter", "/admin/newsletter"], ["Enquiries", "/admin/enquiries"], ["Homepage", "/admin/homepage"], ["Settings", "/admin/settings"]] as const;

export function AdminPanel({ module, startAdding = false }: { module: string; startAdding?: boolean }) {
  const { state, update, reset } = useJewelryStore();
  const [search, setSearch] = useState("");
  const [modal, setModal] = useState<{ action: "view" | "edit" | "add" | "delete"; id?: string } | null>(startAdding ? { action: "add" } : null);
  const [mobileNav, setMobileNav] = useState(false);
  const [toast, setToast] = useState("");
  const [productForm, setProductForm] = useState<Partial<Product>>({});
  const [recordForm, setRecordForm] = useState<DemoRecord>({ id: "", name: "", description: "", status: "Active" });
  const productModule = module === "products";
  const recordKey = moduleLabels[module];
  const rows: (Product | DemoOrder | DemoRecord)[] = productModule ? state.products : module === "orders" ? state.orders : recordKey ? state[recordKey] : [];
  const shown = rows.filter((row) => JSON.stringify(row).toLowerCase().includes(search.toLowerCase()));
  const currentRow = rows.find((row) => row.id === modal?.id);
  const updateRecords = (next: DemoRecord[]) => { if (!recordKey) return; update({ [recordKey]: next } as unknown as Partial<typeof state>); };
  const saveRecord = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (productModule) {
      const values = productForm;
      if (!values.name || !values.price) return;
      const slug = values.name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
      const next: Product = { id: values.id ?? `p-${Date.now()}`, slug, name: values.name, category: values.category ?? "Rings", metal: values.metal ?? "22K Yellow Gold", price: Number(values.price), image: values.image ?? "/images/gold-necklace.png", sku: values.sku ?? `DGJ-${Date.now().toString().slice(-4)}`, description: values.description ?? "Demo product description.", weight: values.weight ?? "Demo", stone: values.stone ?? "Demo details", stock: Number(values.stock ?? 1), featured: Boolean(values.featured), newest: Boolean(values.newest), collection: values.collection ?? "Signature" };
      update({ products: modal?.action === "edit" ? state.products.map((item) => item.id === next.id ? next : item) : [next, ...state.products] });
    } else if (module === "orders") {
      const data = new FormData(event.currentTarget);
      update({ orders: state.orders.map((order) => order.id === modal?.id ? { ...order, status: String(data.get("status")) } : order) });
    } else if (recordKey) {
      const data = new FormData(event.currentTarget);
      const updated = { ...recordForm };
      for (const [key, value] of data.entries()) updated[key] = String(value);
      updated.id = recordForm.id || `${module}-${Date.now()}`;
      updateRecords(modal?.action === "edit" ? (state[recordKey] as DemoRecord[]).map((row) => row.id === updated.id ? updated : row) : [updated, ...(state[recordKey] as DemoRecord[])]);
    }
    setModal(null); setToast("Changes saved.");
  };
  const openModal = (action: "view" | "edit" | "add" | "delete", row?: Product | DemoOrder | DemoRecord) => {
    if (action === "edit" && row && productModule) setProductForm(row as Product);
    if ((action === "edit" || action === "view") && row && !productModule) setRecordForm(row as DemoRecord);
    if (action === "add") { setProductForm({}); setRecordForm({ id: "", name: "", description: "", status: "Active" }); }
    setModal({ action, ...(row ? { id: row.id } : {}) });
  };
  const deleteRow = () => { if (productModule) update({ products: state.products.filter((p) => p.id !== modal?.id) }); else if (module === "orders") update({ orders: state.orders.filter((p) => p.id !== modal?.id) }); else if (recordKey) updateRecords((state[recordKey] as DemoRecord[]).filter((p) => p.id !== modal?.id)); setModal(null); setToast("Demo item deleted."); };
  const names: Record<string, string> = { dashboard: "Overview", products: "Products", categories: "Categories", collections: "Collections", orders: "Orders", customers: "Customers", banners: "Banners", gallery: "Gallery", testimonials: "Testimonials", coupons: "Coupons", newsletter: "Newsletter subscribers", enquiries: "Contact enquiries", homepage: "Homepage content", settings: "Website settings" };
  const stats = [{ label: "Total products", value: state.products.length }, { label: "Categories", value: state.categories.length }, { label: "Total orders", value: state.orders.length }, { label: "Pending orders", value: state.orders.filter((order) => order.status === "Pending").length }];
  const setProductValue = (key: keyof Product, value: string | number | boolean) => setProductForm((current) => ({ ...current, [key]: value }));
  return <div className="flex min-h-screen bg-secondary/45 text-foreground">
    <aside className={`${mobileNav ? "fixed inset-y-0 left-0 z-40 flex" : "hidden"} w-64 shrink-0 flex-col border-r border-border bg-foreground text-background lg:sticky lg:top-0 lg:flex lg:h-screen`}><div className="flex h-[76px] items-center gap-3 border-b border-background/15 px-5"><BrandMark/><span className="font-editorial text-sm">Dhairya<br/>Admin</span><Button variant="ghost" size="icon" onClick={() => setMobileNav(false)} className="ml-auto text-background lg:hidden"><Icon name="close"/></Button></div><nav className="flex-1 overflow-auto px-3 py-5">{adminNav.map(([name, href]) => <Link key={href} to={href} onClick={() => setMobileNav(false)} className={`mb-1 flex h-10 items-center px-3 text-xs tracking-wide transition-colors hover:bg-background/10 ${href === `/admin/${module}` ? "bg-primary/15 text-primary" : "text-background/65"}`}>{name}</Link>)}</nav><div className="border-t border-background/15 p-4"><Link to="/" className="text-xs text-background/65">← View storefront</Link><button onClick={() => { localStorage.removeItem("dhairya-admin-demo-session"); window.location.href = "/admin/login"; }} className="mt-3 block text-xs text-background/65">Sign out of demo</button></div></aside>
    <div className="min-w-0 flex-1"><header className="sticky top-0 z-20 flex h-[76px] items-center justify-between border-b border-border bg-background px-4 sm:px-7"><div className="flex items-center gap-3"><Button variant="ghost" size="icon" aria-label="Open admin navigation" onClick={() => setMobileNav(true)} className="lg:hidden"><Icon name="menu"/></Button><div><p className="text-[9px] tracking-[0.2em] text-muted-foreground">DHAIRYA · DEMO ADMIN</p><h1 className="font-editorial text-xl">{names[module] ?? "Overview"}</h1></div></div><div className="flex items-center gap-3"><span className="hidden text-xs text-muted-foreground sm:inline">Admin · Demo</span><span className="flex size-9 items-center justify-center rounded-full bg-secondary font-editorial">D</span></div></header>
      <main className="mx-auto max-w-[1500px] p-4 sm:p-7">
        {module === "dashboard" ? <><div className="mb-6 flex flex-wrap items-end justify-between gap-3"><div><p className="text-xs text-muted-foreground">A snapshot of your local demo shop.</p></div><Button asChild variant="outline" size="sm"><Link to="/">View storefront</Link></Button></div><div className="grid grid-cols-2 gap-3 xl:grid-cols-4">{stats.map((item) => <div key={item.label} className="border border-border bg-background p-5"><p className="text-[10px] tracking-widest text-muted-foreground">{item.label.toUpperCase()}</p><p className="mt-3 font-editorial text-3xl">{item.value}</p><span className="mt-2 block text-[10px] text-primary">LOCAL DEMO DATA</span></div>)}</div><div className="mt-6 grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><section className="border border-border bg-background p-5"><div className="flex items-center justify-between"><h2 className="font-editorial text-2xl">Recent orders</h2><Link to="/admin/orders" className="text-xs underline">View all</Link></div>{state.orders.length ? <div className="mt-4 divide-y divide-border">{state.orders.slice(0, 5).map((order) => <div key={order.id} className="flex flex-wrap justify-between gap-2 py-3 text-sm"><span>{order.id} · {order.name}</span><span>{money(order.total)} · {order.status}</span></div>)}</div> : <p className="py-10 text-center text-sm text-muted-foreground">Demo orders will appear here after checkout.</p>}</section><section className="border border-border bg-background p-5"><h2 className="font-editorial text-2xl">Sales overview</h2><div className="mt-8 flex h-40 items-end gap-2 border-b border-border">{[42, 66, 53, 85, 58, 95, 69, 76, 48, 88, 61, 100].map((value, i) => <div key={i} className="flex-1 bg-primary/70" style={{ height: `${value}%` }} title={`Sample month ${i + 1}`}/>)}</div><div className="mt-3 flex justify-between text-[9px] tracking-widest text-muted-foreground"><span>JAN</span><span>DEC</span></div><p className="mt-3 text-[10px] text-muted-foreground">Illustrative sales activity · no live transactions</p></section></div><div className="mt-6 grid gap-6 md:grid-cols-2"><section className="border border-border bg-background p-5"><h2 className="font-editorial text-2xl">Recently added</h2><div className="mt-4 divide-y divide-border">{state.products.slice(0, 4).map((p) => <div key={p.id} className="flex items-center gap-3 py-3"><img src={p.image} alt="" className="size-12 object-cover"/><span className="flex-1 text-sm">{p.name}</span><span className="text-sm">{money(p.price)}</span></div>)}</div></section><section className="border border-border bg-background p-5"><h2 className="font-editorial text-2xl">Demo activity</h2><div className="mt-4 grid grid-cols-2 gap-3 text-sm"><div className="border border-border p-4"><span className="text-xs text-muted-foreground">Wishlist items</span><p className="mt-2 font-editorial text-2xl">{state.wishlist.length}</p></div><div className="border border-border p-4"><span className="text-xs text-muted-foreground">Newsletter</span><p className="mt-2 font-editorial text-2xl">{state.newsletter.length}</p></div></div></section></div></> : module === "homepage" ? <section className="max-w-3xl border border-border bg-background p-6"><p className="mb-5 text-sm text-muted-foreground">Edit the message displayed on the storefront home page.</p><form onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); update({ homepage: { heroHeading: String(form.get("heroHeading")), heroDescription: String(form.get("heroDescription")) } }); setToast("Homepage content updated."); }} className="grid gap-5"><label className="grid gap-2 text-[10px] tracking-widest">HERO HEADING<input name="heroHeading" defaultValue={state.homepage.heroHeading} className="h-11 border-b border-border bg-transparent px-1 text-sm"/></label><label className="grid gap-2 text-[10px] tracking-widest">HERO DESCRIPTION<textarea name="heroDescription" defaultValue={state.homepage.heroDescription} rows={3} className="border-b border-border bg-transparent px-1 py-2 text-sm"/></label><Button className="w-fit rounded-none">SAVE HOMEPAGE</Button></form></section> : module === "settings" ? <section className="max-w-3xl border border-border bg-background p-6"><p className="mb-5 text-sm text-muted-foreground">Company details and demo data controls.</p><form onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); const settings = Object.fromEntries([...form.entries()].map(([key, value]) => [key, String(value)])); update({ settings }); setToast("Website settings updated."); }} className="grid gap-4">{Object.entries(state.settings).map(([key, value]) => <label key={key} className="grid gap-2 text-[10px] tracking-widest">{key.toUpperCase()}<input name={key} defaultValue={value} className="h-11 border-b border-border bg-transparent px-1 text-sm"/></label>)}<Button className="w-fit rounded-none">SAVE SETTINGS</Button></form><div className="mt-10 border-t border-border pt-6"><h2 className="font-editorial text-2xl">Reset demonstration data</h2><p className="mt-2 text-sm text-muted-foreground">This restores sample products and clears saved changes, cart, wishlist and demo orders in this browser.</p><Button variant="destructive" className="mt-4" onClick={() => { if (window.confirm("Reset all locally saved demonstration data? This cannot be undone.")) { reset(); setToast("Demo data reset."); } }}>Reset demo data</Button></div></section> : <><div className="mb-5 flex flex-wrap justify-between gap-3"><input aria-label={`Search ${names[module] ?? "records"}`} value={search} onChange={(event) => setSearch(event.target.value)} placeholder={`Search ${names[module]?.toLowerCase() ?? "records"}…`} className="h-10 w-full max-w-xs border-b border-border bg-transparent px-2 text-sm outline-none focus:border-primary"/><Button onClick={() => openModal("add")} className="rounded-none text-[10px] tracking-widest"><Icon name="plus"/> ADD {module === "newsletter" || module === "enquiries" ? "RECORD" : module === "products" ? "PRODUCT" : (names[module] ?? "ITEM").replace(/s$/, "").toUpperCase()}</Button></div><div className="overflow-x-auto border border-border bg-background"><table className="w-full min-w-[780px] text-left text-sm"><thead className="border-b border-border bg-secondary/70 text-[9px] tracking-widest"><tr>{(productModule ? ["Product", "SKU", "Category", "Price", "Stock"] : module === "orders" ? ["Order", "Customer", "Total", "Date", "Status"] : ["Name / details", "Description", "Status", "Record ID"]).map((head) => <th key={head} className="px-4 py-3 font-medium">{head.toUpperCase()}</th>)}<th className="px-4 py-3 font-medium">ACTIONS</th></tr></thead><tbody className="divide-y divide-border">{shown.map((row) => { const product = row as Product; const order = row as DemoOrder; const recordRow = row as DemoRecord; const title = productModule ? product.name : module === "orders" ? order.id : String(recordRow.name ?? recordRow.email ?? recordRow.id); return <tr key={row.id}><td className="px-4 py-3">{productModule ? <span className="flex items-center gap-3"><img src={product.image} alt="" className="size-10 object-cover"/>{title}</span> : title}</td>{productModule ? <><td className="px-4 py-3 text-xs text-muted-foreground">{product.sku}</td><td className="px-4 py-3">{product.category}</td><td className="px-4 py-3">{money(product.price)}</td><td className="px-4 py-3">{product.stock}</td></> : module === "orders" ? <><td className="px-4 py-3">{order.name}</td><td className="px-4 py-3">{money(order.total)}</td><td className="px-4 py-3">{order.date}</td><td className="px-4 py-3">{order.status}</td></> : <><td className="max-w-[210px] truncate px-4 py-3 text-xs text-muted-foreground">{String(recordRow.description ?? recordRow.feedback ?? recordRow.email ?? "—")}</td><td className="px-4 py-3">{String(recordRow.status ?? "—")}</td><td className="px-4 py-3 font-mono text-[10px] text-muted-foreground">{recordRow.id}</td></>}<td className="px-4 py-3"><div className="flex gap-1"><Button variant="outline" size="sm" onClick={() => openModal("view", row)} title="View" aria-label={`View ${title}`} className="h-8 px-2"><Icon name="eye" size={15}/><span className="hidden xl:inline">View</span></Button><Button variant="outline" size="sm" onClick={() => openModal("edit", row)} title="Edit" aria-label={`Edit ${title}`} className="h-8 px-2"><Icon name="edit" size={15}/><span className="hidden xl:inline">Edit</span></Button><Button variant="outline" size="sm" onClick={() => openModal("delete", row)} title="Delete" aria-label={`Delete ${title}`} className="h-8 px-2 text-destructive"><Icon name="trash" size={15}/><span className="hidden xl:inline">Delete</span></Button></div></td></tr>; })}</tbody></table>{shown.length === 0 && <p className="p-10 text-center text-sm text-muted-foreground">No records to show yet. Add one to begin.</p>}</div><p className="mt-3 text-xs text-muted-foreground">Showing {shown.length} of {rows.length} records · Saved only in this browser</p></>}
      </main>
    </div>
    {toast && <div role="status" className="fixed bottom-5 right-5 z-50 border border-primary bg-background px-5 py-3 text-sm shadow-lg">{toast}<button onClick={() => setToast("")} className="ml-4 text-primary">×</button></div>}
    {modal && <div role="dialog" aria-modal="true" aria-label={`${modal.action} ${names[module]}`} className="fixed inset-0 z-50 flex items-center justify-center bg-foreground/55 p-4" onMouseDown={(event) => { if (event.target === event.currentTarget) setModal(null); }}><div className="max-h-[90vh] w-full max-w-xl overflow-auto bg-background p-6"><div className="flex items-start justify-between"><div><p className="text-[9px] tracking-widest text-primary">DEMO {names[module]?.toUpperCase()}</p><h2 className="mt-1 font-editorial text-2xl">{modal.action === "add" ? "Add new record" : modal.action === "delete" ? "Confirm deletion" : `${modal.action[0]?.toUpperCase()}${modal.action.slice(1)} details`}</h2></div><Button variant="ghost" size="icon" aria-label="Close dialog" onClick={() => setModal(null)}><Icon name="close"/></Button></div>{modal.action === "delete" ? <><p className="mt-6 text-sm leading-6 text-muted-foreground">This removes the selected item from this browser’s demo data. This cannot be undone.</p><div className="mt-6 flex justify-end gap-2"><Button variant="outline" onClick={() => setModal(null)}>Cancel</Button><Button variant="destructive" onClick={deleteRow}>Delete</Button></div></> : modal.action === "view" ? <div className="mt-5 grid gap-3">{productModule && <img src={(currentRow as Product | undefined)?.image} alt="" className="max-h-72 w-full object-contain"/>}{Object.entries(currentRow ?? {}).filter(([key]) => key !== "image").map(([key, value]) => <div key={key} className="grid grid-cols-[130px_1fr] gap-3 border-b border-border py-2 text-sm"><span className="text-[10px] tracking-widest text-muted-foreground">{key.toUpperCase()}</span><span className="break-words">{typeof value === "object" ? JSON.stringify(value) : String(value)}</span></div>)}</div> : <form onSubmit={saveRecord} className="mt-5 grid gap-4">{productModule ? <>{[["name", "Product name"], ["sku", "SKU"], ["category", "Category"], ["collection", "Collection"], ["price", "Price (INR)"], ["metal", "Metal type"], ["weight", "Weight (demo)"], ["stone", "Stone details (demo)"], ["stock", "Stock quantity"], ["image", "Image path"]].map(([key, label]) => <label key={key} className="grid gap-1 text-[9px] tracking-widest">{label.toUpperCase()}<input required={key === "name" || key === "price"} type={key === "price" || key === "stock" ? "number" : "text"} value={String(productForm[key as keyof Product] ?? "")} onChange={(e) => setProductValue(key as keyof Product, key === "price" || key === "stock" ? Number(e.target.value) : e.target.value)} className="h-10 border-b border-border bg-transparent px-1 text-sm outline-none focus:border-primary"/></label>)}<label className="grid gap-1 text-[9px] tracking-widest">DESCRIPTION<textarea value={String(productForm.description ?? "")} onChange={(e) => setProductValue("description", e.target.value)} className="border-b border-border bg-transparent px-1 py-2 text-sm" rows={3}/></label><div className="flex flex-wrap gap-4 text-xs"><label className="flex items-center gap-2"><input type="checkbox" checked={Boolean(productForm.featured)} onChange={(e) => setProductValue("featured", e.target.checked)}/> Featured</label><label className="flex items-center gap-2"><input type="checkbox" checked={Boolean(productForm.newest)} onChange={(e) => setProductValue("newest", e.target.checked)}/> New arrival</label></div><p className="text-[10px] text-muted-foreground">For a demo image upload, place an image in public/images and enter its path above.</p></> : module === "orders" ? <><p className="text-sm">Order {modal.id}</p><label className="grid gap-2 text-[10px] tracking-widest">ORDER STATUS<select name="status" defaultValue={(currentRow as DemoOrder | undefined)?.status} className="h-10 border-b border-border bg-background text-sm">{["Pending", "Confirmed", "Processing", "Shipped", "Delivered", "Cancelled"].map((status) => <option key={status}>{status}</option>)}</select></label></> : (module === "settings" ? [] : ["name", "email", "phone", "category", "description", "feedback", "rating", "discount", "validity", "status", "image"]).map((key) => <label key={key} className="grid gap-1 text-[9px] tracking-widest">{key.toUpperCase()}<input name={key} defaultValue={String(recordForm[key] ?? "")} type={key === "rating" ? "number" : "text"} className="h-10 border-b border-border bg-transparent px-1 text-sm"/></label>)}<div className="mt-2 flex justify-end gap-2"><Button type="button" variant="outline" onClick={() => setModal(null)}>Cancel</Button><Button type="submit">{modal.action === "add" ? "Add record" : "Save changes"}</Button></div></form>}</div></div>}
  </div>;
}

export function JewelryApp({ page }: { page: PageName }) {
  const children: Record<PageName, ReactNode> = { home: <HomePage/>, shop: <ShopPage/>, collections: <CollectionsPage/>, "new-arrivals": <ShopPage arrivalsOnly/>, about: <EditorialPage kind="about"/>, craftsmanship: <EditorialPage kind="craftsmanship"/>, gallery: <GalleryPage/>, contact: <ContactPage/>, cart: <CartPage/>, wishlist: <WishlistPage/>, checkout: <CheckoutPage/> };
  return <PublicLayout>{children[page]}</PublicLayout>;
}

export function AdminLoginPage() { return <AdminLogin/>; }
function slugify(v: string) { return v.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""); }

function CollectionDetailInner({ slug }: { slug: string }) {
  const { state } = useJewelryStore();
  const name = collections.find((c) => slugify(c) === slug);
  if (!name) return <div className="page-enter"><PageIntro eyebrow="COLLECTIONS" title="Collection not found" copy="This collection may have been renamed or removed."/><div className="py-10 text-center"><Button asChild className="rounded-none"><Link to="/collections">ALL COLLECTIONS</Link></Button></div></div>;
  const products = state.products.filter((p) => p.collection.toLowerCase() === name.toLowerCase());
  const record = state.collections.find((c) => String(c["name"]).toLowerCase() === name.toLowerCase());
  const banner = products[0]?.image ?? "/images/gold-necklace.png";
  return <div className="page-enter">
    <section className="relative h-[52vh] min-h-[360px] overflow-hidden bg-foreground"><img src={banner} alt={`${name} collection`} className="size-full object-cover opacity-70"/><div className="absolute inset-0 bg-gradient-to-t from-foreground/80 to-transparent"/><div className="absolute inset-x-0 bottom-10 mx-auto max-w-[1440px] px-5 text-background md:px-12"><p className="text-[10px] tracking-[0.25em] text-primary">THE COLLECTION</p><h1 className="mt-3 font-editorial text-5xl sm:text-6xl">{name} Collection</h1><p className="mt-4 max-w-xl text-sm leading-7 text-background/75">{String(record?.["description"] ?? "A curated edit of considered designs.")}</p></div></section>
    <section className="mx-auto max-w-[1440px] px-5 py-14 md:px-12"><div className="mb-8 flex items-center justify-between"><p className="text-[10px] tracking-widest text-muted-foreground">{products.length} DESIGNS</p><Link to="/collections" className="text-[10px] tracking-widest text-primary">← ALL COLLECTIONS</Link></div>{products.length ? <div className="grid grid-cols-2 gap-x-5 gap-y-10 lg:grid-cols-4">{products.map((p) => <ProductCard key={p.id} product={p}/>)}</div> : <p className="py-16 text-center text-sm text-muted-foreground">No designs in this collection yet.</p>}</section>
  </div>;
}
export function CollectionDetail({ slug }: { slug: string }) { return <PublicLayout><CollectionDetailInner slug={slug}/></PublicLayout>; }

function SearchInner() {
  const { state } = useJewelryStore();
  const [q, setQ] = useState("");
  useEffect(() => { setQ(new URLSearchParams(window.location.search).get("q") ?? ""); }, []);
  const term = q.trim().toLowerCase();
  const results = term ? state.products.filter((p) => [p.name, p.category, p.collection, p.metal].some((v) => v.toLowerCase().includes(term))) : [];
  const cols = term ? collections.filter((c) => c.toLowerCase().includes(term)) : [];
  return <div className="page-enter"><PageIntro eyebrow="SEARCH" title="Find a design" copy="Search by name, category, metal or collection."/>
    <section className="mx-auto max-w-[1440px] px-5 py-10 md:px-12">
      <form onSubmit={(e) => { e.preventDefault(); window.history.replaceState(null, "", `/search?q=${encodeURIComponent(q)}`); }} className="mx-auto flex max-w-2xl gap-2"><input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Try rings, bridal, diamond…" aria-label="Search jewellery" className="h-12 min-w-0 flex-1 border-b border-border bg-transparent px-2 text-sm outline-none focus:border-primary"/>{q && <Button type="button" variant="outline" className="h-12 rounded-none" onClick={() => setQ("")}>CLEAR</Button>}</form>
      {cols.length > 0 && <div className="mt-8 flex flex-wrap justify-center gap-2">{cols.map((c) => <Link key={c} to="/collections/$slug" params={{ slug: slugify(c) }} className="border border-primary/60 px-4 py-2 text-[10px] tracking-widest text-primary">{c.toUpperCase()} COLLECTION</Link>)}</div>}
      {term && <p className="mt-10 text-[10px] tracking-widest text-muted-foreground">{results.length} RESULTS FOR “{q}”</p>}
      {term && !results.length ? <div className="py-16 text-center"><p className="font-editorial text-3xl">No designs found</p><p className="mt-2 text-sm text-muted-foreground">Try a different word, or browse the full shop.</p><Button asChild className="mt-6 rounded-none"><Link to="/shop">BROWSE SHOP</Link></Button></div> : <div className="mt-6 grid grid-cols-2 gap-x-5 gap-y-10 lg:grid-cols-4">{results.map((p) => <ProductCard key={p.id} product={p}/>)}</div>}
    </section></div>;
}
export function SearchResults() { return <PublicLayout><SearchInner/></PublicLayout>; }

function ConfirmationInner() {
  const { state, ready } = useJewelryStore();
  const [id, setId] = useState<string | null>(null);
  useEffect(() => { setId(localStorage.getItem("dhairya-last-order") ?? ""); }, []);
  if (!ready || id === null) return <div className="py-32"/>;
  const order = state.orders.find((o) => o.id === id);
  if (!order) return <div className="page-enter"><PageIntro eyebrow="ORDER" title="No recent order" copy="Place a demo order to see its confirmation here."/><div className="py-10 text-center"><Button asChild className="rounded-none"><Link to="/shop">SHOP DESIGNS</Link></Button></div></div>;
  return <div className="page-enter mx-auto max-w-3xl px-5 py-20">
    <div className="text-center"><span className="mx-auto flex size-14 items-center justify-center border border-primary font-editorial text-2xl text-primary">✓</span><p className="mt-6 text-[10px] tracking-widest text-primary">DEMO ORDER CONFIRMED</p><h1 className="mt-3 font-editorial text-4xl">Thank you, {order.name}</h1><p className="mt-3 text-sm text-muted-foreground">Order <strong className="text-foreground">{order.id}</strong> · {order.date} · saved locally, no payment taken.</p></div>
    <div className="mt-10 grid gap-6 sm:grid-cols-2"><div className="border border-border p-6"><h2 className="font-editorial text-2xl">Order summary</h2>{order.items.map((line) => { const p = state.products.find((x) => x.id === line.productId); return p ? <div key={line.productId} className="mt-4 flex items-center gap-3"><img src={p.image} alt={p.name} className="size-14 object-cover"/><div className="flex-1 text-sm">{p.name}<p className="text-xs text-muted-foreground">Qty {line.quantity}</p></div><span className="text-sm">{money(p.price * line.quantity)}</span></div> : null; })}<p className="mt-5 flex justify-between border-t border-border pt-4 text-sm"><span>Total</span><strong>{money(order.total)}</strong></p></div>
    <div className="border border-border p-6 text-sm leading-7"><h2 className="font-editorial text-2xl">Delivery details</h2><p className="mt-3">{order.name}<br/>{order.email}<br/>{order.phone}<br/>{order.address}</p><p className="mt-4 text-xs text-muted-foreground">Estimated delivery: 7–10 business days (illustrative only).</p></div></div>
    <div className="mt-10 text-center"><Button asChild className="rounded-none"><Link to="/shop">CONTINUE SHOPPING</Link></Button></div>
  </div>;
}
export function OrderConfirmation() { return <PublicLayout><ConfirmationInner/></PublicLayout>; }

export function ProtectedAdminPanel({ module, startAdding = false }: { module: string; startAdding?: boolean }) {
  const [authed, setAuthed] = useState<boolean | null>(null);
  useEffect(() => {
    const ok = localStorage.getItem("dhairya-admin-demo-session") === "active";
    if (module === "login" && ok) { window.location.replace("/admin/dashboard"); return; }
    if (module !== "login" && !ok) { window.location.replace("/admin/login"); return; }
    setAuthed(ok);
  }, [module]);
  if (authed === null) return <div className="min-h-screen bg-background"/>;
  return module === "login" ? <AdminLogin/> : <AdminPanel module={module} startAdding={startAdding}/>;
}
